def VTask.memPartition {α : Type u_1} (f : ℕ → Set α) (n : ℕ) : Set (Set α) :=
match n with
| 0 => {univ}
| _ =>
  let prev_partition := VTask.memPartition f (n - 1);
  let mut current_partition : List (Set α) := [];
  for s in prev_partition do
    current_partition := current_partition ++ [
      s ∩ f (n - 1),
      s \ f (n - 1)
    ];
  current_partition.toSet
